// src/core/calendar/stem-branch.ts
var STEMS = ["Gi\xE1p", "\u1EA4t", "B\xEDnh", "\u0110inh", "M\u1EADu", "K\u1EF7", "Canh", "T\xE2n", "Nh\xE2m", "Qu\xFD"];
var BRANCHES = ["T\xFD", "S\u1EEDu", "D\u1EA7n", "M\xE3o", "Th\xECn", "T\u1EF5", "Ng\u1ECD", "M\xF9i", "Th\xE2n", "D\u1EADu", "Tu\u1EA5t", "H\u1EE3i"];
var mod = (n, m) => (n % m + m) % m;
var stemName = (stem) => STEMS[mod(stem, 10)];
var branchName = (branch) => BRANCHES[mod(branch, 12)];
var stemBranchName = ({ stem, branch }) => `${stemName(stem)} ${branchName(branch)}`;
var stemPolarity = (stem) => mod(stem, 2) === 0 ? "D\u01B0\u01A1ng" : "\xC2m";
var branchPolarity = (branch) => mod(branch, 2) === 0 ? "D\u01B0\u01A1ng" : "\xC2m";
var normalizeName = (text) => text.trim().normalize("NFC").toLowerCase();
var STEM_LOOKUP = new Map(STEMS.map((name, i) => [name.toLowerCase(), i]));
var BRANCH_LOOKUP = new Map([
  ...BRANCHES.map((name, i) => [name.toLowerCase(), i]),
  ["t\xED", 0],
  ["t\u1ECB", 5]
]);
function parseStem(text) {
  const found = STEM_LOOKUP.get(normalizeName(text));
  return found === void 0 ? err(`Kh\xF4ng nh\u1EADn ra thi\xEAn can "${text}". H\u1EE3p l\u1EC7: ${STEMS.join(", ")}`) : ok(found);
}
function parseBranch(text) {
  const found = BRANCH_LOOKUP.get(normalizeName(text));
  return found === void 0 ? err(`Kh\xF4ng nh\u1EADn ra \u0111\u1ECBa chi "${text}". H\u1EE3p l\u1EC7: ${BRANCHES.join(", ")}`) : ok(found);
}
function parseStemBranch(text) {
  const parts = text.trim().normalize("NFC").split(/\s+/);
  if (parts.length !== 2) return err(`Can chi ph\u1EA3i g\u1ED3m hai ch\u1EEF, v\xED d\u1EE5 "Gi\xE1p T\xFD"; nh\u1EADn \u0111\u01B0\u1EE3c "${text}"`);
  const stem = parseStem(parts[0]);
  if (!stem.ok) return stem;
  const branch = parseBranch(parts[1]);
  if (!branch.ok) return branch;
  if (mod(stem.value, 2) !== mod(branch.value, 2)) {
    return err(`"${text}" kh\xF4ng c\xF3 trong 60 hoa gi\xE1p: can v\xE0 chi ph\u1EA3i c\xF9ng \xE2m ho\u1EB7c c\xF9ng d\u01B0\u01A1ng`);
  }
  return ok({ stem: stem.value, branch: branch.value });
}
var sexagenaryIndex = ({ stem, branch }) => mod(6 * stem - 5 * branch, 60);
var yearStemBranch = (lunarYear) => ({
  stem: mod(lunarYear - 4, 10),
  branch: mod(lunarYear - 4, 12)
});
var firstMonthStem = (yearStem) => mod((mod(yearStem, 5) + 1) * 2, 10);
var monthStemBranch = (yearStem, lunarMonth) => ({
  stem: mod(firstMonthStem(yearStem) + lunarMonth - 1, 10),
  branch: mod(lunarMonth + 1, 12)
});
var dayStemBranch = (julianDay) => ({
  stem: mod(julianDay + 9, 10),
  branch: mod(julianDay + 1, 12)
});
var ratHourStem = (dayStem2) => mod(mod(dayStem2, 5) * 2, 10);
var hourStemBranch = (dayStem2, hourBranch) => ({
  stem: mod(ratHourStem(dayStem2) + hourBranch, 10),
  branch: mod(hourBranch, 12)
});
var decadeLeaderBranch = ({ stem, branch }) => mod(branch - stem, 12);
var tuanVoidBranches = (stemBranch) => {
  const leader = decadeLeaderBranch(stemBranch);
  return [mod(leader + 10, 12), mod(leader + 11, 12)];
};

// src/agent/reading-request.ts
var READING_COMMAND = "/xem";
var READING_USAGE = [
  "C\xE1ch d\xF9ng: /xem <ng\xE0y/th\xE1ng/n\u0103m> <gi\u1EDD> <nam|n\u1EEF> [t\xEAn]",
  "  /xem 15/8/1990 9:10 nam",
  "  /xem \xE2m 25/6/1990 T\u1EF5 n\u1EEF Lan",
  "  /xem \xE2m nhu\u1EADn 10/2/2023 Th\xECn nam"
].join("\n");
var DATE_PATTERN = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/;
var CLOCK_PATTERN = /^(\d{1,2})(?::|h)(\d{2})?$/;
var GENDERS = { nam: "nam", "n\u1EEF": "n\u1EEF", nu: "n\u1EEF" };
var LUNAR_FLAGS = /* @__PURE__ */ new Set(["\xE2m", "am", "\xE2m-l\u1ECBch"]);
var LEAP_FLAGS = /* @__PURE__ */ new Set(["nhu\u1EADn", "nhuan"]);
var normalizeToken = (token) => token.normalize("NFC").toLowerCase();
var isTimeToken = (token) => CLOCK_PATTERN.test(token) || parseBranch(token).ok;
function parseReadingCommand(text) {
  const tokens = text.trim().normalize("NFC").split(/\s+/).slice(1);
  const lowered = tokens.map(normalizeToken);
  const dateIndex = tokens.findIndex((token) => DATE_PATTERN.test(token));
  const genderIndex = lowered.findIndex((token) => GENDERS[token] !== void 0);
  const timeIndex = tokens.findIndex((token, index) => index !== dateIndex && isTimeToken(token));
  if (dateIndex < 0) return err(`Thi\u1EBFu ng\xE0y sinh d\u1EA1ng ng\xE0y/th\xE1ng/n\u0103m.
${READING_USAGE}`);
  if (timeIndex < 0) return err(`Thi\u1EBFu gi\u1EDD sinh (v\xED d\u1EE5 9:10 ho\u1EB7c t\xEAn canh gi\u1EDD nh\u01B0 T\u1EF5).
${READING_USAGE}`);
  if (genderIndex < 0) return err(`Thi\u1EBFu gi\u1EDBi t\xEDnh (nam ho\u1EB7c n\u1EEF).
${READING_USAGE}`);
  const [, day, month, year] = DATE_PATTERN.exec(tokens[dateIndex]);
  const isLunar = lowered.some((token) => LUNAR_FLAGS.has(token));
  const isLeapMonth = lowered.some((token) => LEAP_FLAGS.has(token));
  if (isLeapMonth && !isLunar) return err("Th\xE1ng nhu\u1EADn ch\u1EC9 d\xF9ng v\u1EDBi ng\xE0y \xE2m l\u1ECBch (th\xEAm ch\u1EEF '\xE2m').");
  const used = /* @__PURE__ */ new Set([dateIndex, timeIndex, genderIndex]);
  const name = tokens.filter((_token, index) => !used.has(index) && !LUNAR_FLAGS.has(lowered[index]) && !LEAP_FLAGS.has(lowered[index])).join(" ");
  return ok({
    calendar: isLunar ? "\xE2m l\u1ECBch" : "d\u01B0\u01A1ng l\u1ECBch",
    day: Number(day),
    month: Number(month),
    year: Number(year),
    isLeapMonth,
    time: tokens[timeIndex],
    gender: GENDERS[lowered[genderIndex]],
    name
  });
}
function buildReadingPrompt(request) {
  const date5 = `${request.day}/${request.month}${request.isLeapMonth ? " (th\xE1ng nhu\u1EADn)" : ""}/${request.year} ${request.calendar}`;
  const person = request.name ? `T\xEAn: ${request.name}. ` : "";
  return [
    `H\xE3y xem tr\u1ECDn l\xE1 s\u1ED1 T\u1EED Vi Nam Ph\xE1i cho t\xF4i. ${person}T\xF4i sinh ng\xE0y ${date5}, gi\u1EDD ${request.time}, gi\u1EDBi t\xEDnh ${request.gender}.`,
    "Ph\xE2n t\xEDch chi ti\u1EBFt m\u1ECDi ph\u1EA7n c\u1EE7a l\xE1 s\u1ED1: ch\xEDnh tinh, ph\u1EE5 tinh, T\u1EE9 H\xF3a, Tu\u1EA7n Tri\u1EC7t, v\xF2ng Th\xE1i Tu\u1EBF, B\xE1c S\u0129, Tr\xE0ng Sinh, cung xung chi\u1EBFu v\xE0 c\xE1c cung ph\u1EE5 tr\u1EE3, tam ph\u01B0\u01A1ng t\u1EE9 ch\xEDnh, c\xE1ch c\u1EE5c, m\u01B0\u1EDDi hai cung v\xE0 t\u1EEBng \u0111\u1EA1i v\u1EADn m\u01B0\u1EDDi n\u0103m.",
    "M\u1ED7i lu\u1EADn gi\u1EA3i ph\u1EA3i c\xF3 l\u1EADp lu\u1EADn ch\u1EB7t ch\u1EBD: d\u1EEF ki\u1EC7n tr\xEAn l\xE1 s\u1ED1, quy t\u1EAFc c\u1ED5 th\u01B0 di\u1EC5n \u0111\u1EA1t b\u1EB1ng l\u1EDDi th\u01B0\u1EDDng, r\u1ED3i m\u1EDBi \u0111\u1EBFn k\u1EBFt lu\u1EADn, vi\u1EBFt d\u1EC5 hi\u1EC3u cho ng\u01B0\u1EDDi kh\xF4ng chuy\xEAn.",
    "Cu\u1ED1i c\xF9ng, t\u1EEB l\xE1 s\u1ED1 h\xE3y \u0111\u01B0a ra l\u1EDDi khuy\xEAn h\u1EE3p l\xFD v\u1EC1 s\u1EF1 nghi\u1EC7p, c\xF4ng vi\u1EC7c, gia \u0111\xECnh, t\xECnh c\u1EA3m v\xE0 s\u1EE9c kh\u1ECFe: vi\u1EC7c n\xEAn l\xE0m v\xE0 vi\u1EC7c n\xEAn tr\xE1nh, m\u1ED7i l\u1EDDi khuy\xEAn g\u1EAFn v\u1EDBi d\u1EEF ki\u1EC7n c\u1EE5 th\u1EC3 tr\xEAn l\xE1 s\u1ED1."
  ].join("\n");
}

