  if (row2.sinh === name) return "Sinh \u0111\u1ECBa";
  if (row2.vuong === name) return "V\u01B0\u1EE3ng \u0111\u1ECBa";
  if (row2.bai === name) return "B\u1EA1i \u0111\u1ECBa";
