var consecutiveTransformations = (ctx) => {
  const branches = TAM_HOA.map((name) => ctx.chart.palaces.find((palace) => hasStarIn(palace, name))?.branch);
  if (branches.some((branch) => branch === void 0)) return condition("\u0111\u1EE7 ba H\xF3a L\u1ED9c, Quy\u1EC1n, Khoa tr\xEAn l\xE1 s\u1ED1", false);
  const present = branches;
  const consecutive = Array.from({ length: 12 }, (_, start) => start).find(
    (start) => present.every((branch) => [0, 1, 2].includes(mod(branch - start, 12)))
  );
  const distinct = new Set(present).size === 3;
  const met = consecutive !== void 0 && distinct && present.includes(ctx.life.branch);
  return condition(`Khoa Quy\u1EC1n L\u1ED9c \u0111i li\u1EC1n 3 cung, M\u1EC7nh c\xF3 1 H\xF3a (H\xF3a t\u1EA1i ${present.map(branchName).join(", ")})`, met);
};
