// src/kb/search.ts
function scoreDocument(doc, terms) {
  let score = 0;
  for (const t of [...terms.bigrams, ...terms.words]) {
    const f = foldVi(t);
    if (doc.fold.title.includes(f)) score += 3;
    if (doc.fold.questions.includes(f)) score += 2;
    if (doc.fold.keywords.includes(f)) score += 2;
    if (doc.fold.body.includes(f)) score += 1;
  }
  return score;
}
function makeSnippet(doc, terms, max = 220) {
  const lines2 = doc.body.split("\n").filter((l) => l.trim() && !l.startsWith("#"));
  const candidates = [...terms.bigrams, ...terms.words].map(foldVi);
  const line = candidates.map((c) => lines2.find((l) => foldVi(l).includes(c))).find(Boolean) ?? lines2[0] ?? "";
  const clean = line.replace(/\s+/g, " ").trim();
  return clean.length > max ? `${clean.slice(0, max)}\u2026` : clean;
}
function searchKb(index, query, opts = {}) {
  const terms = queryTerms(query);
  if (terms.words.length === 0) return [];
  const limit = Math.min(Math.max(opts.limit ?? 8, 1), 25);
  const pool = opts.branch ? index.docs.filter((d) => d.branch === opts.branch) : index.docs;
  return pool.map((doc) => ({ doc, score: scoreDocument(doc, terms) })).filter((h) => h.score > 0).sort((a, b) => b.score - a.score || a.doc.path.localeCompare(b.doc.path)).slice(0, limit).map((h) => ({ ...h, snippet: makeSnippet(h.doc, terms) }));
}

