import fs3 from "node:fs/promises";
import path4 from "node:path";
var PathEscapeError = class extends Error {
};
async function resolveInside(root, untrusted) {
  const rootReal = await fs3.realpath(root);
  const target = path4.resolve(rootReal, untrusted);
  assertInside(rootReal, target, untrusted);
  const real = await fs3.realpath(target).catch(() => {
    throw new Error(`Kh\xF4ng t\u1ED3n t\u1EA1i: ${untrusted}`);
  });
  assertInside(rootReal, real, untrusted);
  return real;
}
function assertInside(root, target, label) {
  const rel = path4.relative(root, target);
  if (rel === ".." || rel.startsWith(`..${path4.sep}`) || path4.isAbsolute(rel)) {
    throw new PathEscapeError(`\u0110\u01B0\u1EDDng d\u1EABn n\u1EB1m ngo\xE0i th\u01B0 m\u1EE5c cho ph\xE9p: ${label}`);
  }
}

