async function listMarkdown(dir) {
  const out = [];
  const entries = await fs4.readdir(dir, { withFileTypes: true, recursive: true });
  for (const e of entries) {
    if (e.isFile() && e.name.endsWith(".md") && e.name !== "README.md") out.push(path5.join(e.parentPath, e.name));
  }
  return out.sort();
}
