function slotPlacements(ctx, slot, palaces) {
  for (const alternative of slot) {
    const found = alternative.map((token) => tokenPlacements(ctx, token, true).find((placement) => palaces.includes(placement.palace)));
    if (found.every((placement) => placement !== void 0)) return found;
  }
  return null;
}
function starSetTrigger(rule) {
  return {
    id: rule.id,
    name: rule.name,
    goals: rule.goals,
    polarity: rule.polarity,
    certainty: "interpretive",
    assumptions: [
      SCOPE_ASSUMPTION,
      NATAL_AND_FLOWING_ASSUMPTION,
      ...rule.mainStars ? [MAIN_GROUP_ASSUMPTION] : [],
      ...rule.assumptions ?? [],
      NO_BREAKERS_ASSUMPTION
    ],
    source: rule.source,
    kbFile: rule.kbFile,
    test(ctx) {
      const matches = rule.anchors.flatMap((anchor2) => {
        const branch = resolveTarget(ctx, anchor2);
        if (branch === null) return [];
        const main3 = rule.mainStars ? hasMainStar(ctx, branch, rule.mainStars) : [];
        if (rule.mainStars && !main3.length) return [];
        const palaces = scopePalaces2(branch, rule.scope);
        const placements = rule.slots.map((slot) => slotPlacements(ctx, slot, palaces));
        if (placements.some((found) => found === null)) return [];
        const used = placements.flatMap((found) => found);
        const text = `${targetLabel(anchor2)} ${palaceText2(ctx.chart, branch)}${main3.length ? ` c\xF3 ${main3.join(", ")}` : ""}: ${used.map((placement) => placementText(ctx, placement)).join("; ")}`;
        return [{ text, decade: anchor2.frame === "major" && used.every((placement) => !placement.flowing) }];
      });
      return splitByScale(
        matches.filter((match) => !match.decade).map((match) => match.text),
        matches.filter((match) => match.decade).map((match) => match.text)
      );
    }
  };
}
