async function main2() {
  const config2 = loadConfig();
  const kb = await loadKb(config2.kbRoot);
  const server = createTuViMcpServer(ALL_TOOLS, {
    kb,
    corpusRoot: config2.corpusRoot,
    charts: createWorkspaceChartStore(config2.chartDir)
  });
  await server.connect(new StdioServerTransport());
  process.stderr.write(`tu-vi-nam-phai MCP: ${ALL_TOOLS.length} tool, kho ${kb.docs.length} file, ${config2.kbRoot}
`);
}
main2().catch((error62) => {
  process.stderr.write(`tu-vi-nam-phai MCP l\u1ED7i kh\u1EDFi \u0111\u1ED9ng: ${error62 instanceof Error ? error62.message : String(error62)}
`);
  process.exit(1);
});
